+#[cfg(unix)]
+fn set_ignore_signal(signal: Signal) {
+    let _ = unsafe { sigaction(signal, &SigAction::new(SigHandler::SigIgn, SaFlags::empty(), SigSet::all())) };
+}

 fn make_options(matches: &clap::ArgMatches) -> UResult<Options<'_>> {
     let ignore_env = matches.get_flag("ignore-environment");
@@ -107,6 +118,10 @@ fn make_options(matches: &clap::ArgMatches) -> UResult<Options<'_>> {
     let running_directory = matches.get_one::<OsString>("chdir").map(|s| s.as_os_str());
