+
+#[uucore::main]
+pub fn uumain(args: impl uucore::Args) -> UResult<()> {
+    let matches = uu_app().try_get_matches_from(args)?;
+    let opts = make_options(&matches)?;
+
+    // Apply ignore signals
+    #[cfg(unix)]
+    for signal in &opts.ignore_signals {
+        set_ignore_signal(*signal);
+    }
+
+    apply_removal_of_all_env_vars(&opts);
+    apply_unset(&opts);
+    apply_set(&opts);
+    apply_files(&opts);
+
+    if opts.program.is_empty() {
+        print_env(opts.line_ending);
+        return Ok(());
+    }
+
+    let do_debug_printing = matches.get_flag("verbose");
+    let mut arg0 = Cow::Borrowed(opts.program[0]);
+
+    let mut cmd = process::Command::new(&*arg0);
+    cmd.args(&opts.program[1..]);
+
+    if let Some(_argv0) = opts.argv0 {
+        #[cfg(unix)]
+        {
+            cmd.arg0(_argv0);
+            arg0 = Cow::Borrowed(_argv0);
+            if do_debug_printing {
+                eprintln!("argv0:     {}", arg0.quote());
+            }
+        }
+
+        #[cfg(not(unix))]
+        return Err(USimpleError::new(
+            2,
+            "--argv0 is currently not supported on this platform",
+        ));
+    }
+
+    if do_debug_printing {
+        eprintln!("executing: {}", arg0.maybe_quote());
+        let arg_prefix = "   arg";
+        eprintln!("{}[{}]= {}", arg_prefix, 0, arg0.quote());
+        for (i, arg) in opts.program.iter().enumerate().skip(1) {
+            eprintln!("{}[{}]= {}", arg_prefix, i, arg.quote());
+        }
+    }
+
+    match cmd.status() {
+        Ok(exit) if !exit.success() => {
+            #[cfg(unix)]
+            if let Some(exit_code) = exit.code() {
+                return Err(exit_code.into());
+            } else {
+                // `exit.code()` returns `None` on Unix when the process is terminated by a signal.
+                // See std::os::unix::process::ExitStatusExt for more information. This prints out
+                // the interrupted process and the signal it received.
+                let signal_code = exit.signal().unwrap();
+                let signal = Signal::try_from(signal_code).unwrap();
+
+                // We have to disable any handler that's installed by default.
+                // This ensures that we exit on this signal.
+                // For example, `SIGSEGV` and `SIGBUS` have default handlers installed in Rust.
+                // We ignore the errors because there is not much we can do if that fails anyway.
+                // SAFETY: The function is unsafe because installing functions is unsafe, but we are
+                // just defaulting to default behavior and not installing a function. Hence, the call
+                // is safe.
+                let _ = unsafe {
+                    sigaction(
+                        signal,
+                        &SigAction::new(SigHandler::SigDfl, SaFlags::empty(), SigSet::all()),
+                    )
+                };
+
+                let _ = raise(signal);
+            }
+            return Err(exit.code().unwrap().into());
+        }
+        Err(ref err)
+            if (err.kind() == io::ErrorKind::NotFound)
+                || (err.kind() == io::ErrorKind::InvalidInput) =>
+        {
+            return Err(make_error_no_such_file_or_dir(arg0.deref()));
+        }
+        Err(e) => {
+            uucore::show_error!("unknown error: {:?}", e);
+            return Err(126.into());
+        }
+        Ok(_) => (),
+    }
+    Ok(())
+}
+
+fn apply_removal_of_all_env_vars(opts: &Options<'_>) {
+    // remove all env vars if told to ignore presets
+    if opts.ignore_env {
+        for (ref name, _) in env::vars_os() {
+            env::remove_var(name);
+        }
+    }
+}
+
+fn apply_unset(opts: &Options<'_>) {
+    for name in &opts.unsets {
+        env::remove_var(name);
+    }
+}
+
+fn apply_set(opts: &Options<'_>) {
+    for (name, value) in &opts.sets {
+        env::set_var(name, value);
+    }
+}
+
+fn apply_files(opts: &Options<'_>) {
+    for file in &opts.files {
+        let ini = Ini::load_from_file(file)
+            .map_err(|e| USimpleError::new(1, format!("cannot read {:?}: {}", file.quote(), e)))
+            .unwrap_or_else(|e| {
+                uucore::show_error!("{}", e);
+                std::process::exit(1);
+            });
+        for (section, props) in ini.sections() {
+            for (key, value) in props.iter() {
+                if section.is_none() || section.as_ref().unwrap().is_empty() {
+                    env::set_var(key, value);
+                }
+            }
+        }
+    }
+}
+
+fn make_error_no_such_file_or_dir(prog: &OsStr) -> Box<dyn UError> {
+    USimpleError::new(127, format!("{}: No such file or directory", prog.quote())).into()
+}
+
+pub fn uu_app() -> Command {
+    Command::new(uucore::util_name())
+        .version(crate_version!())
+        .about(ABOUT)
+        .override_usage(format_usage(USAGE))
+        .infer_long_args(true)
+        .arg(
+            Arg::new("ignore-environment")
+                .short('i')
+                .long("ignore-environment")
+                .help("start with an empty environment")
+                .action(ArgAction::SetTrue),
+        )
+        .arg(
+            Arg::new("chdir")
+                .short('C')
+                .long("chdir")
+                .value_name("DIR")
+                .help("change working directory to DIR")
+                .value_parser(ValueParser::os_string()),
+        )
+        .arg(
+            Arg::new("file")
+                .short('f')
+                .long("file")
+                .value_name("FILE")
+                .help("read and set variables from FILE")
+                .action(ArgAction::Append)
+                .value_parser(ValueParser::os_string()),
+        )
+        .arg(
+            Arg::new("unset")
+                .short('u')
+                .long("unset")
+                .value_name("NAME")
+                .help("remove variable from the environment")
+                .action(ArgAction::Append)
+                .value_parser(ValueParser::os_string()),
+        )
+        .arg(
+            Arg::new("ignore-signal")
+                .long("ignore-signal")
+                .value_name("SIG")
+                .help(IGNORE_SIGNAL_HELP)
+                .action(ArgAction::Append),
+        )
+        .arg(
+            Arg::new("verbose")
+                .short('v')
+                .long("verbose")
+                .help("print the environment before running the command")
+                .action(ArgAction::SetTrue),
+        )
+        .arg(
+            Arg::new("replace")
+                .short('r')
+                .long("replace")
+                .value_name("NAME=VALUE")
+                .help("replace NAME=VALUE in the environment")
+                .action(ArgAction::Append),
+        )
+        .arg(
+            Arg::new("argv0")
+                .short('S')
+                .long("argv0")
+                .value_name("NAME")
+                .help("pass NAME as the zero argument to COMMAND")
+                .value_parser(ValueParser::os_string()),
+        )
+        .arg(
+            Arg::new("")
+                .hide(true)
+                .action(ArgAction::Append),
+        )
+        .arg(
+            Arg::new("null")
+                .short('0')
+                .long("null")
+                .help("end each output line with NUL, not newline")
+                .action(ArgAction::SetTrue),
+        )
+}
